import 'package:firebase_auth/firebase_auth.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';

import 'firebase_options.dart';
import 'records_page.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  String? setupError;
  User? user;
  try {
    // Initialize this platform with the options generated by FlutterFire CLI.
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
    // Anonymous sign-in lets the database rules protect each user's own data.
    final credential = await FirebaseAuth.instance.signInAnonymously();
    user = credential.user;
    if (user == null) {
      throw StateError('Firebase Authentication returned no signed-in user.');
    }
  } catch (error) {
    setupError = error.toString();
  }

  runApp(PracticalNineApp(user: user, setupError: setupError));
}

class PracticalNineApp extends StatelessWidget {
  const PracticalNineApp({
    super.key,
    required this.user,
    required this.setupError,
  });

  final User? user;
  final String? setupError;

  @override
  Widget build(BuildContext context) {
    const blue = Color(0xFF1959A6);
    return MaterialApp(
      title: 'Firebase Database',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(
          seedColor: blue,
          brightness: Brightness.light,
        ),
        useMaterial3: true,
        scaffoldBackgroundColor: const Color(0xFFF4F8FD),
        inputDecorationTheme: InputDecorationTheme(
          filled: true,
          fillColor: Colors.white,
          border: OutlineInputBorder(
            borderRadius: BorderRadius.circular(14),
            borderSide: BorderSide.none,
          ),
          enabledBorder: OutlineInputBorder(
            borderRadius: BorderRadius.circular(14),
            borderSide: const BorderSide(color: Color(0xFFDCE6F2)),
          ),
          focusedBorder: OutlineInputBorder(
            borderRadius: BorderRadius.circular(14),
            borderSide: const BorderSide(color: blue, width: 1.5),
          ),
        ),
      ),
      home: user != null
          ? RecordsPage(userId: user!.uid)
          : FirebaseSetupPage(error: setupError ?? 'Unknown Firebase error.'),
    );
  }
}

class FirebaseSetupPage extends StatelessWidget {
  const FirebaseSetupPage({super.key, required this.error});

  final String error;

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).colorScheme;
    return Scaffold(
      appBar: AppBar(
        title: const Text('Firebase Database'),
        backgroundColor: colors.surface,
      ),
      body: Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 680),
          child: SingleChildScrollView(
            padding: const EdgeInsets.all(24),
            child: Card(
              color: Colors.white,
              child: Padding(
                padding: const EdgeInsets.all(24),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Icon(Icons.cloud_off, size: 44, color: colors.primary),
                    const SizedBox(height: 16),
                    Text(
                      'Firebase setup required',
                      style: Theme.of(context).textTheme.headlineSmall
                          ?.copyWith(fontWeight: FontWeight.bold),
                    ),
                    const SizedBox(height: 8),
                    const Text(
                      'This project has no Firebase credentials yet, so it '
                      'has not connected to a database. Create a Firebase '
                      'project, enable Realtime Database and Anonymous '
                      'Authentication, then run the FlutterFire setup '
                      'instructions in practical_9/README.md.',
                    ),
                    const SizedBox(height: 20),
                    Text(
                      'Initialization details',
                      style: Theme.of(context).textTheme.titleMedium,
                    ),
                    const SizedBox(height: 8),
                    SelectableText(error),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}
